options.getOption:
// Free taxis within 1.5 km of a rain gauge, against the usual number there, by the
// rain the gauge measured in the 30 minutes before. One bar per class of rain: the
// median change over the week's gauge-hours in that class, with the middle half
// of them (the 25th to the 75th percentile) as a line through the bar, so a bar
// that leans one way while its line spans both sides reads as weak. No clicks.

// @constants begin
const CLASSES = ['Dry', 'Under 1 mm', '1 to 5 mm', '5 mm or more'];
// The map's rain bands: no rain in grey, then darker to lighter blue as more falls.
const COLOURS = ['#8e8e8e', '#1f4e80', '#2b7bc4', '#3fa0e8'];
// @constants end

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const grid = theme.colors.border.weak;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v === null || v === undefined ? null : Number(v));

const byClass = new Map();
col('rain_class').forEach((c, i) => {
  byClass.set(String(c), {
    change: num(col('change')[i]),
    q1: num(col('q1')[i]),
    q3: num(col('q3')[i]),
    hours: num(col('hours')[i]),
  });
});

// Top to bottom: dry first. A category axis draws bottom up, so reverse.
const rows = CLASSES.map((c, i) => ({ c, colour: COLOURS[i], ...(byClass.get(c) ?? {}) })).reverse();
const pct = (v) => (v === null || v === undefined || Number.isNaN(v) ? '–' : `${v > 0 ? '+' : ''}${Math.round(v * 100)} %`);

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 8, bottom: 28, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const r = rows[p.dataIndex];
      if (!r || r.hours === undefined) return `${r?.c ?? ''}: no hours`;
      return `<b>${r.c}</b> in the 30 minutes before<br/>` +
        `Median change: <b>${pct(r.change)}</b><br/>` +
        `Middle half of the hours: ${pct(r.q1)} to ${pct(r.q3)}<br/>` +
        `${r.hours} gauge-hours`;
    },
  },
  xAxis: {
    type: 'value',
    name: 'Free taxis around the gauge, against usual',
    nameLocation: 'middle',
    nameGap: 20,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, formatter: (v) => pct(v) },
    splitLine: { lineStyle: { color: grid } },
  },
  yAxis: {
    type: 'category',
    data: rows.map((r) => r.c),
    axisLabel: {
      color: text,
      lineHeight: 16,
      // The class, and under it its median change and the gauge-hours behind it.
      formatter: (value, index) => {
        const r = rows[index];
        return r.hours ? `${value}\n{fig|${pct(r.change)} · ${r.hours} h}` : `${value}\n{fig|no hours}`;
      },
      rich: { fig: { color: muted, fontSize: 11 } },
    },
    axisLine: { lineStyle: { color: grid } },
    axisTick: { show: false },
  },
  series: [
    {
      type: 'bar',
      barWidth: '55%',
      data: rows.map((r) => ({ value: r.change ?? null, itemStyle: { color: r.colour } })),
      markLine: {
        silent: true,
        symbol: 'none',
        lineStyle: { color: muted, type: 'solid' },
        label: { show: false },
        data: [{ xAxis: 0 }],
      },
    },
    {
      // The middle half of the hours: a line from the 25th to the 75th percentile.
      type: 'custom',
      silent: true,
      renderItem: (params, api) => {
        const lo = api.value(0);
        const hi = api.value(1);
        if (lo === null || hi === null || Number.isNaN(lo) || Number.isNaN(hi)) return null;
        const a = api.coord([lo, params.dataIndex]);
        const b = api.coord([hi, params.dataIndex]);
        const h = 6;
        const style = { stroke: text, lineWidth: 1.5, opacity: 0.8 };
        return {
          type: 'group',
          children: [
            { type: 'line', shape: { x1: a[0], y1: a[1], x2: b[0], y2: b[1] }, style },
            { type: 'line', shape: { x1: a[0], y1: a[1] - h / 2, x2: a[0], y2: a[1] + h / 2 }, style },
            { type: 'line', shape: { x1: b[0], y1: b[1] - h / 2, x2: b[0], y2: b[1] + h / 2 }, style },
          ],
        };
      },
      encode: { x: [0, 1], y: 2 },
      data: rows.map((r, i) => [r.q1 ?? null, r.q3 ?? null, i]),
      z: 3,
    },
  ],
};

