options.getOption:
// Free taxis across Singapore through the day, hour by hour of Singapore time: the
// median of the week's weekdays, the median of its weekends and public holidays,
// and today so far. No clicks.

// @constants begin
const KINDS = [
  { kind: 'Weekday', name: 'Weekday, median', colour: '#8AB8FF', dash: 'solid' },
  { kind: 'Weekend or holiday', name: 'Weekend or holiday, median', colour: '#B877D9', dash: 'dashed' },
];
const TODAY = { name: 'Today', colour: '#FADE2A' };
// @constants end

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const grid = theme.colors.border.weak;

const frameOf = (refId) => context.panel.data.series.find((f) => f.refId === refId);
const colOf = (frame, name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v === null || v === undefined ? null : Number(v));

const hours = Array.from({ length: 24 }, (_, h) => h);
const label = (h) => `${String(h).padStart(2, '0')}:00`;

const usual = frameOf('A');
const series = KINDS.map((k) => {
  const values = new Array(24).fill(null);
  colOf(usual, 'day_kind').forEach((kind, i) => {
    if (String(kind) === k.kind) values[num(colOf(usual, 'sg_hour')[i])] = num(colOf(usual, 'taxis')[i]);
  });
  return {
    name: k.name,
    type: 'line',
    data: values,
    showSymbol: false,
    lineStyle: { color: k.colour, width: 2, type: k.dash },
    itemStyle: { color: k.colour },
  };
});

const today = frameOf('B');
const todayValues = new Array(24).fill(null);
colOf(today, 'sg_hour').forEach((h, i) => {
  todayValues[num(h)] = num(colOf(today, 'taxis')[i]);
});
series.push({
  name: TODAY.name,
  type: 'line',
  data: todayValues,
  showSymbol: true,
  symbolSize: 5,
  lineStyle: { color: TODAY.colour, width: 3 },
  itemStyle: { color: TODAY.colour },
  z: 5,
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 34, bottom: 28, containLabel: true },
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 18 },
  tooltip: {
    trigger: 'axis',
    valueFormatter: (v) => (v === null || v === undefined ? '–' : `${Math.round(v).toLocaleString('en')} taxis`),
  },
  xAxis: {
    type: 'category',
    data: hours.map(label),
    boundaryGap: false,
    axisLabel: { color: muted, interval: 2 },
    axisLine: { lineStyle: { color: grid } },
    name: 'Singapore time',
    nameLocation: 'middle',
    nameGap: 24,
    nameTextStyle: { color: muted },
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted, formatter: (v) => v.toLocaleString('en') },
    splitLine: { lineStyle: { color: grid } },
  },
  series,
};

